-- Finance-owned schema only. No Connect tables, production data, or retired QuickBooks tokens.
CREATE TABLE finance_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE finance_daycare_entries (id INTEGER PRIMARY KEY AUTOINCREMENT, period TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT '', entry_type TEXT NOT NULL DEFAULT 'actual', amount_cents INTEGER NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT 'manual', created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX idx_finance_daycare_period ON finance_daycare_entries(period);
CREATE TABLE finance_church_entries (id INTEGER PRIMARY KEY AUTOINCREMENT, fiscal_year INTEGER NOT NULL, period_month INTEGER NOT NULL DEFAULT 0, classification TEXT NOT NULL, category_path TEXT NOT NULL, account_name TEXT NOT NULL, depth INTEGER NOT NULL DEFAULT 0, has_children INTEGER NOT NULL DEFAULT 0, own_actual_cents INTEGER NOT NULL DEFAULT 0, own_budget_cents INTEGER, account_qbo_id TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT 'import', notes TEXT NOT NULL DEFAULT '', synced_at TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(fiscal_year, period_month, category_path, source));
CREATE INDEX idx_church_entries_year ON finance_church_entries(fiscal_year);
CREATE INDEX idx_church_entries_year_class ON finance_church_entries(fiscal_year, classification);
CREATE INDEX idx_church_entries_path ON finance_church_entries(category_path);
CREATE INDEX idx_church_entries_source_synced ON finance_church_entries(source, synced_at);
CREATE TABLE finance_church_balances (id INTEGER PRIMARY KEY AUTOINCREMENT, fiscal_year INTEGER NOT NULL, as_of_date TEXT NOT NULL DEFAULT '', classification TEXT NOT NULL, category_path TEXT NOT NULL, account_name TEXT NOT NULL, depth INTEGER NOT NULL DEFAULT 0, has_children INTEGER NOT NULL DEFAULT 0, own_balance_cents INTEGER NOT NULL DEFAULT 0, source TEXT NOT NULL DEFAULT 'import', synced_at TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(fiscal_year, category_path, source));
CREATE INDEX idx_church_balances_year ON finance_church_balances(fiscal_year);
CREATE INDEX idx_church_balances_source_synced ON finance_church_balances(source, synced_at);
CREATE TABLE finance_property_monthly (property_key TEXT NOT NULL DEFAULT 'ivanhoe', period TEXT NOT NULL, occupancy_pct REAL, total_revenue_cents INTEGER, total_expenses_cents INTEGER, net_income_cents INTEGER, net_operating_income_cents INTEGER, available_for_distribution_cents INTEGER, reserve_balance_cents INTEGER, source_report TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT (datetime('now')), loan_payment_cents INTEGER, interest_expense_cents INTEGER, PRIMARY KEY(property_key, period));
CREATE TABLE finance_property_distributions (id INTEGER PRIMARY KEY AUTOINCREMENT, property_key TEXT NOT NULL DEFAULT 'ivanhoe', period TEXT NOT NULL, amount_cents INTEGER NOT NULL DEFAULT 0, UNIQUE(property_key, period));
CREATE INDEX idx_finance_property_dist_key ON finance_property_distributions(property_key);
CREATE TABLE finance_property_reserves (property_key TEXT NOT NULL DEFAULT 'ivanhoe', reserve_key TEXT NOT NULL, report_month TEXT NOT NULL, tax_year INTEGER, target_estimate_cents INTEGER, reserve_before_cents INTEGER, contribution_cents INTEGER, reserve_after_cents INTEGER, note TEXT NOT NULL DEFAULT '', PRIMARY KEY(property_key, reserve_key, report_month));
CREATE TABLE finance_property_reserve_disbursements (id INTEGER PRIMARY KEY AUTOINCREMENT, property_key TEXT NOT NULL DEFAULT 'ivanhoe', reserve_key TEXT NOT NULL, period_key TEXT NOT NULL, amount_cents INTEGER, paid_via_report_month TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', UNIQUE(property_key, reserve_key, period_key));
CREATE TABLE finance_property_capital_ledger (id INTEGER PRIMARY KEY AUTOINCREMENT, property_key TEXT NOT NULL DEFAULT 'ivanhoe', entry_date TEXT NOT NULL DEFAULT '', amount_cents INTEGER NOT NULL DEFAULT 0, payee TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', check_ref TEXT NOT NULL DEFAULT '', project TEXT NOT NULL DEFAULT '', sort_order INTEGER NOT NULL DEFAULT 0);
CREATE INDEX idx_finance_property_capital_ledger_key ON finance_property_capital_ledger(property_key);
CREATE TABLE finance_property_repairs (id INTEGER PRIMARY KEY AUTOINCREMENT, property_key TEXT NOT NULL DEFAULT 'ivanhoe', entry_date TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', amount_cents INTEGER, payee TEXT NOT NULL DEFAULT '', capitalized INTEGER NOT NULL DEFAULT 0);
CREATE INDEX idx_finance_property_repairs_key ON finance_property_repairs(property_key);
CREATE TABLE finance_budget_plan (category TEXT NOT NULL, classification TEXT NOT NULL DEFAULT 'Expenses', fiscal_year INTEGER NOT NULL, planned_amount_cents INTEGER NOT NULL DEFAULT 0, basis TEXT NOT NULL DEFAULT 'manual', growth_pct REAL, base_amount_cents INTEGER, notes TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT (datetime('now')), PRIMARY KEY(category, fiscal_year));
CREATE INDEX idx_finance_budget_plan_year ON finance_budget_plan(fiscal_year);
CREATE TABLE finance_property_budget_monthly (property_key TEXT NOT NULL DEFAULT 'ivanhoe', period TEXT NOT NULL, revenue_cents INTEGER NOT NULL DEFAULT 0, expenses_cents INTEGER NOT NULL DEFAULT 0, net_income_cents INTEGER NOT NULL DEFAULT 0, source TEXT NOT NULL DEFAULT 'ahra_import', updated_at TEXT NOT NULL DEFAULT (datetime('now')), PRIMARY KEY(property_key, period));
CREATE TABLE finance_daycare_rooms (id INTEGER PRIMARY KEY AUTOINCREMENT, period TEXT NOT NULL, room_name TEXT NOT NULL, capacity_per_day REAL, avg_daily_enrolled REAL, billed_cents INTEGER, labor_cost_cents INTEGER, waitlist_families INTEGER NOT NULL DEFAULT 0, seasonal INTEGER NOT NULL DEFAULT 0, synced_at TEXT NOT NULL DEFAULT '', UNIQUE(period, room_name));
CREATE INDEX idx_finance_daycare_rooms_period ON finance_daycare_rooms(period);
CREATE TABLE finance_import_log (importer_key TEXT PRIMARY KEY, last_imported_at TEXT NOT NULL, note TEXT NOT NULL DEFAULT '');
